#!/usr/bin/env python3
"""Apply the authenticated HYZoraX Control Center V1.8.2 UI patch."""

from __future__ import annotations

import argparse
import base64
import hashlib
import os
import pathlib
import stat
import tempfile
import zlib


VERSION = "1.8.2"
FILES = {
    'internal/web/static/index.html': {
        'before': '8c78fed6b8c7e210b2d814d514652fdb215507cf30e7d54a317702ac16e57522',
        'after': 'c28838761f662e1efda15570ae52683817af29f238b88ea5c15f9c798e47e1a1',
        'payload': '',
    },
    'internal/web/static/app.css': {
        'before': '0e6cbf2195aef540688fe5416359863960bf730c32ec2c566d04d3be7677c23b',
        'after': '0d3ab1908821983d461c449b2ddc614a355f22b4c9886c67ef7edcaa007b500c',
        'payload': '',
    },
    'internal/web/static/app.js': {
        'before': '4796f8adbc27e2ae8066861f7f84af5889d2c6a3d4e9ef2e4ebd9dd015969dee',
        'after': '7fb9695274f55ce33f9eec39637694e83eec22f35025bba77d1bafcec01b3437',
        'payload': '',
    },
    'internal/web/assets_test.go': {
        'before': '6a2d8a465e6d484cb20d1091eca3e24ddfb3f2c0916620c8ce6c3f2d8719158b',
        'after': 'e3200fad0cd81c948bb7995afb76e8b3f4f914fc223b37585cede79874ea247c',
        'payload': '',
    },
    'internal/httpapi/app_test.go': {
        'before': '2adf050923ba4feee2d9cf9927b3aa28e60fa27f70629942cc7619cd5fea0e05',
        'after': '4367bdf342297e2949723c43bb13675ffa71fa599ccc4eb3bf52a855da114603',
        'payload': '',
    },
}


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("source_root", type=pathlib.Path)
    args = parser.parse_args()
    root = args.source_root.resolve()
    if not (root / "go.mod").is_file():
        raise SystemExit(f"not a HYZoraX source root: {root}")

    prepared: list[tuple[pathlib.Path, bytes, int]] = []
    for relative, metadata in FILES.items():
        target = root / relative
        if not target.is_file():
            raise SystemExit(f"required baseline file is missing: {relative}")
        current = target.read_bytes()
        current_hash = sha256(current)
        if current_hash != metadata["before"]:
            raise SystemExit(
                f"baseline mismatch for {relative}: expected "
                f"{metadata['before']}, got {current_hash}"
            )
        replacement = zlib.decompress(base64.b64decode(metadata["payload"], validate=True))
        replacement_hash = sha256(replacement)
        if replacement_hash != metadata["after"]:
            raise SystemExit(f"embedded payload failed authentication: {relative}")
        prepared.append((target, replacement, stat.S_IMODE(target.stat().st_mode)))

    staged: list[tuple[pathlib.Path, pathlib.Path]] = []
    try:
        for target, replacement, mode in prepared:
            descriptor, temporary_name = tempfile.mkstemp(
                prefix=f".{target.name}.v182.", dir=target.parent
            )
            temporary = pathlib.Path(temporary_name)
            with os.fdopen(descriptor, "wb") as handle:
                handle.write(replacement)
                handle.flush()
                os.fsync(handle.fileno())
            temporary.chmod(mode)
            staged.append((target, temporary))
        for target, temporary in staged:
            os.replace(temporary, target)
        staged.clear()
    finally:
        for _, temporary in staged:
            temporary.unlink(missing_ok=True)

    for relative, metadata in FILES.items():
        actual = sha256((root / relative).read_bytes())
        if actual != metadata["after"]:
            raise SystemExit(f"post-write verification failed: {relative}")
    print(f"HYZoraX Control Center V{VERSION} patch applied and verified")


if __name__ == "__main__":
    main()
